<?php

namespace Tests\Feature;

use App\Models\Setting;
use App\Support\Updater\UpdatePaths;
use App\Support\Upload18\BundledKey;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\File;
use Tests\TestCase;
use ZipArchive;

/**
 * Migration 2026_10_25_140100_replace_retired_upload18_key: the master key that example.sql of 1.2.0-1.2.2
 * carried was regenerated by Upload18 and no longer works. A site that still has exactly that key gets the restricted
 * "AVDBCMS public download" key the 1.2.3 package ships, read from the package while the migration runs (never from
 * code). These tests use a made-up retired key and a made-up shipped key: no real key is in them.
 */
class Upload18PublicKeyMigrationTest extends TestCase
{
    use RefreshDatabase;

    private const MIGRATION = '2026_10_25_140100_replace_retired_upload18_key';

    private const RETIRED = 'retiredTestKey0000000000000AB';

    private const SHIPPED = 'u18r_TESTpublicDownloadKey0123456789abcdefgh';

    private string $dir;

    protected function setUp(): void
    {
        parent::setUp();

        $this->dir = storage_path('framework/testing/bundled-key-'.bin2hex(random_bytes(4)));
        File::ensureDirectoryExists($this->dir);

        BundledKey::$retiredHashes = [hash('sha256', self::RETIRED)];
        BundledKey::$exampleSqlPath = $this->dir.'/example.sql';
        BundledKey::$updatePaths = new UpdatePaths($this->dir.'/site', $this->dir.'/site/storage');
        $this->exampleSql(self::SHIPPED);
    }

    protected function tearDown(): void
    {
        BundledKey::$retiredHashes = null;
        BundledKey::$exampleSqlPath = null;
        BundledKey::$updatePaths = null;
        File::deleteDirectory($this->dir);

        parent::tearDown();
    }

    public function test_a_site_still_on_the_retired_key_gets_the_shipped_key_once(): void
    {
        $this->storedKey(self::RETIRED);
        $this->assertSame(self::RETIRED, Setting::getGroup('uploads')['upload18_api_key']);

        $this->migrate();

        $this->assertSame(self::SHIPPED, $this->value());
        $this->assertSame(self::SHIPPED, Setting::getGroup('uploads')['upload18_api_key'], 'the settings cache was cleared');
        $this->assertSame(1, $this->audits());
        $this->assertStringNotContainsString(self::SHIPPED, (string) DB::table('admin_audit_logs')->value('details'));

        $this->migrate();

        $this->assertSame(self::SHIPPED, $this->value());
        $this->assertSame(1, $this->audits(), 'safe to run again');
    }

    public function test_an_owners_own_key_and_an_empty_field_are_never_touched(): void
    {
        foreach (['u18r_OwnersOwnRestrictedKey00000000000000000', ''] as $own) {
            $this->storedKey($own);
            $this->migrate();

            $this->assertSame($own, $this->value());
            $this->assertSame(0, $this->audits());
        }
    }

    public function test_no_settings_row_and_the_retired_key_in_env_gets_a_row(): void
    {
        DB::table('settings')->where('key', 'upload18_api_key')->delete();
        config(['services.upload18.api_key' => self::RETIRED]);

        $this->migrate();

        $this->assertSame(self::SHIPPED, $this->value());
        $this->assertSame('uploads', DB::table('settings')->where('key', 'upload18_api_key')->value('group'));
    }

    public function test_nothing_changes_without_a_usable_shipped_key(): void
    {
        foreach ([self::RETIRED, '', "has spaces and 'quotes' in it", null] as $shipped) {
            $this->storedKey(self::RETIRED);

            if ($shipped === null) {
                File::delete($this->dir.'/example.sql');
            } else {
                $this->exampleSql($shipped);
            }

            $this->migrate();

            $this->assertSame(self::RETIRED, $this->value());
            $this->assertSame(0, $this->audits());
        }
    }

    public function test_a_one_click_update_reads_the_key_from_its_package(): void
    {
        if (! class_exists(ZipArchive::class)) {
            $this->markTestSkipped('ZipArchive is not available.');
        }

        // The updater never writes database/install/: the site keeps the example.sql of its first version.
        $this->exampleSql(self::RETIRED);
        $this->storedKey(self::RETIRED);

        $work = $this->dir.'/site/storage/app/updates';
        File::ensureDirectoryExists($work.'/1.2.3');
        $zip = new ZipArchive();
        $zip->open($work.'/1.2.3/avdbcms-update-1.2.3.zip', ZipArchive::CREATE | ZipArchive::OVERWRITE);
        $zip->addFromString('database/install/example.sql', $this->sql(self::SHIPPED));
        $zip->close();

        file_put_contents($work.'/plan.json', json_encode([
            'format' => 1, 'kind' => 'update', 'status' => 'migrating', 'version' => '1.2.3', 'from' => '1.2.2', 'job' => '1.2.3',
            'release' => ['version' => '1.2.3', 'zip' => ['name' => 'avdbcms-update-1.2.3.zip']],
        ]));

        $this->migrate();
        $this->assertSame(self::SHIPPED, $this->value());

        // Not while no update is being finished (an old plan that is done).
        $this->storedKey(self::RETIRED);
        file_put_contents($work.'/plan.json', json_encode([
            'format' => 1, 'kind' => 'update', 'status' => 'done', 'job' => '1.2.3',
            'release' => ['zip' => ['name' => 'avdbcms-update-1.2.3.zip']],
        ]));
        $this->migrate();
        $this->assertSame(self::RETIRED, $this->value());
    }

    public function test_only_the_hash_of_the_retired_key_is_in_the_code(): void
    {
        BundledKey::$retiredHashes = null;
        BundledKey::$exampleSqlPath = null;

        $this->assertNotEmpty(BundledKey::RETIRED_SHA256);
        foreach (BundledKey::RETIRED_SHA256 as $hash) {
            $this->assertMatchesRegularExpression('/^[0-9a-f]{64}$/', $hash);
        }

        // The project's own example.sql: in the development tree it still holds the retired key (so the hash is right
        // and nothing is "shipped"); in a release package the release build wrote the public download key there.
        $stream = fopen(base_path('database/install/example.sql'), 'rb');
        $key = BundledKey::keyFromSqlStream($stream);
        fclose($stream);

        $this->assertNotNull($key);

        if (BundledKey::isRetired($key)) {
            $this->assertNull(BundledKey::shippedKey());
        } else {
            $this->assertSame($key === '' ? null : $key, BundledKey::shippedKey());
        }

        foreach (['app/Support/Upload18/BundledKey.php', 'database/migrations/'.self::MIGRATION.'.php'] as $file) {
            $this->assertDoesNotMatchRegularExpression('/u18[rt]_[A-Za-z0-9]{8,}/', (string) file_get_contents(base_path($file)), $file);
        }
    }

    private function migrate(): void
    {
        $migration = require database_path('migrations/'.self::MIGRATION.'.php');
        $migration->up();
    }

    private function storedKey(string $value): void
    {
        DB::table('admin_audit_logs')->delete();
        DB::table('settings')->updateOrInsert(['key' => 'upload18_api_key'], ['value' => $value, 'group' => 'uploads', 'updated_at' => now()->subDay()]);
        Setting::clearCache();
    }

    private function value(): ?string
    {
        return DB::table('settings')->where('key', 'upload18_api_key')->value('value');
    }

    private function audits(): int
    {
        return DB::table('admin_audit_logs')->where('action', BundledKey::AUDIT_ACTION)->count();
    }

    private function exampleSql(string $key): void
    {
        file_put_contents($this->dir.'/example.sql', $this->sql($key));
    }

    private function sql(string $key): string
    {
        return "LOCK TABLES `settings` WRITE;\nINSERT INTO `settings` VALUES\n"
            ."(30,'mail_from_name','AVDBCMS','email','2026-04-25 07:17:05','2026-05-05 03:55:31'),\n"
            ."(31,'upload18_api_key','".str_replace("'", "''", $key)."','uploads','2026-04-25 10:06:23','2026-04-25 10:06:23'),\n"
            ."(32,'upload18_api_url','https://upload18.org/api','uploads','2026-04-25 10:06:23','2026-04-25 10:06:23');\n";
    }
}
